  "evidence_basis": [
    {
      "evidence_id": "F02_M0_ACTIONS",
      "source_type": "M0",
      "source_path": "ignition/reports/evaluations/ignition-220-cognitive-evolution-r0/families/FAMILY02/m0.md",
